<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#111}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}.total{text-align:right;font-size:20px;font-weight:bold}</style></head><body><h1>FuelOps Invoice #{{ $sale->id }}</h1><p>Date: {{ $sale->sale_date->format('Y-m-d H:i') }}</p><p>Customer: {{ $sale->customer?->name ?? 'Walk-in customer' }}</p><table><thead><tr><th>Fuel</th><th>Liters</th><th>Price/L</th><th>Subtotal</th></tr></thead><tbody>@foreach($sale->details as $detail)<tr><td>{{ $detail->fuel->fuel_name }}</td><td>{{ $detail->liters }}</td><td>{{ $detail->price_per_liter }}</td><td>{{ $detail->subtotal }}</td></tr>@endforeach</tbody></table><p class="total">Total: RWF {{ number_format($sale->total_amount, 2) }}</p></body></html>

